package com.garagedesk.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank;
@Entity @Table(name="vehicles") public class Vehicle { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @NotBlank @Column(nullable=false,unique=true) String registrationNumber; @NotBlank String model; @NotBlank String ownerName; @NotBlank String ownerPhone; public Vehicle(){} public Vehicle(String r,String m,String o,String p){registrationNumber=r;model=m;ownerName=o;ownerPhone=p;} public Long getId(){return id;} public String getRegistrationNumber(){return registrationNumber;} public void setRegistrationNumber(String v){registrationNumber=v;} public String getModel(){return model;} public void setModel(String v){model=v;} public String getOwnerName(){return ownerName;} public void setOwnerName(String v){ownerName=v;} public String getOwnerPhone(){return ownerPhone;} public void setOwnerPhone(String v){ownerPhone=v;} }
